function obterCoresAnelRanking(posicao: number): [string, string, string] {
  if (posicao === 0) return ['#FFF7BF', '#F7C948', '#A16207'];
  if (posicao === 1) return ['#FFFFFF', '#CBD5E1', '#64748B'];
  if (posicao === 2) return ['#FFD6A3', '#CD7F32', '#7C2D12'];
  return ['#67E8F9', '#38BDF8', '#2563EB'];
}

function obterCorPodio(posicao: number) {
  if (posicao === 0) return '#FFD84D';
  if (posicao === 1) return '#DCE6F1';
  if (posicao === 2) return '#D98B48';
  return '#38BDF8';
}
