function obterQuizSemanal() {
  const inicio = new Date(2026, 0, 5).getTime();
  const agora = new Date();
  agora.setHours(0, 0, 0, 0);
  const semanaMs = 7 * 24 * 60 * 60 * 1000;
  const indice = Math.floor((agora.getTime() - inicio) / semanaMs);
  const indiceSeguro = ((indice % QUIZZES_SEMANAIS.length) + QUIZZES_SEMANAIS.length) % QUIZZES_SEMANAIS.length;
  return QUIZZES_SEMANAIS[indiceSeguro];
}

function fotosPorUidParaNomes(fotosPorUid: Record<string, unknown>) {
  return Object.entries(fotosPorUid).reduce((acc, [uid, foto]) => {
    const nome = UID_TO_NOME[uid];
    if (nome && typeof foto === 'string') acc[nome] = foto;
    return acc;
  }, {} as Record<string, string>);
}

function formatarNomeUsuario(valor?: string | null) {
  if (!valor) return 'Participante';

  if (valor.trim().toLowerCase() === 'mundotecnologia@gmail.com') {
    return 'Admin';
  }

  const textoBase = valor.includes('@') ? valor.split('@')[0] : valor;
  const textoComEspacos = textoBase
    .replace(/[._-]+/g, ' ')
    .replace(/\d+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  if (!textoComEspacos) return 'Participante';

  return textoComEspacos
    .split(' ')
    .map(parte => parte.charAt(0).toUpperCase() + parte.slice(1).toLowerCase())
    .join(' ');
}

function obterDiaPublicacao(data: Date = new Date()) {
  const partes = new Intl.DateTimeFormat('pt-BR', {
    timeZone: 'America/Sao_Paulo',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  }).formatToParts(data);

  const ano = partes.find(parte => parte.type === 'year')?.value;
  const mes = partes.find(parte => parte.type === 'month')?.value;
  const dia = partes.find(parte => parte.type === 'day')?.value;

  return `${ano}-${mes}-${dia}`;
}

function versiculoFoiPublicadoNoDia(versiculo: VersiculoDia, dia: string) {
  if (versiculo.diaPublicacao) return versiculo.diaPublicacao === dia;
  if (!versiculo.criadoEm?.toDate) return false;

  return obterDiaPublicacao(versiculo.criadoEm.toDate()) === dia;
}

function formatarHorarioMensagem(mensagem: MensagemChat) {
  if (!mensagem.criadoEm?.toDate) return 'Agora';

  return new Intl.DateTimeFormat('pt-BR', {
    hour: '2-digit',
    minute: '2-digit',
    timeZone: 'America/Sao_Paulo',
  }).format(mensagem.criadoEm.toDate());
}

function normalizarLinkExterno(valor?: string) {
  const link = String(valor || '').trim();
  if (!link) return '';
  if (/^https?:\/\//i.test(link)) return link;
  if (/^(www\.)?(youtube\.com|youtu\.be)\//i.test(link)) return `https://${link}`;
  return '';
}

function extrairListaYoutube(link?: string) {
  const linkNormalizado = normalizarLinkExterno(link);
  if (!linkNormalizado) return '';
  const resultado = linkNormalizado.match(/[?&]list=([^&#]+)/i);
  return resultado?.[1] ? decodeURIComponent(resultado[1]) : '';
}

function listaYoutubePodeSerCompartilhada(lista?: string) {
  const idLista = String(lista || '').trim().toUpperCase();
  if (!idLista) return false;

  /*
   * RD é uma Mix dinâmica. WL, LL, UL, FL e LM são listas
   * pessoais ou automáticas que podem depender da conta conectada.
   * Esses tipos não devem ser convertidos para /playlist?list=...
   * porque o YouTube pode responder que a playlist não pode ser exibida.
   */
  return !['RD', 'WL', 'LL', 'UL', 'FL', 'LM']
    .some(prefixo => idLista.startsWith(prefixo));
}

function extrairVideoDeMixYoutube(lista?: string) {
  const idLista = String(lista || '').trim();

  /*
   * Uma Mix simples costuma usar RD + o ID do vídeo inicial.
   * Exemplo: RDypjYFqLaGN4 -> ypjYFqLaGN4.
   */
  const resultado = idLista.match(/^RD(?:MM)?([A-Za-z0-9_-]{11})$/i);
  return resultado?.[1] || '';
}

function extrairVideoIdYoutube(link?: string) {
  const linkNormalizado = normalizarLinkExterno(link);
  if (!linkNormalizado) return '';

  const padroes = [
    /youtu\.be\/([A-Za-z0-9_-]{6,})/i,
    /[?&]v=([A-Za-z0-9_-]{6,})/i,
    /youtube\.com\/(?:shorts|embed|live)\/([A-Za-z0-9_-]{6,})/i,
  ];

  for (const padrao of padroes) {
    const resultado = linkNormalizado.match(padrao);
    if (resultado?.[1]) return resultado[1];
  }

  return '';
}

function obterLinkYoutubeMusica(musica: MusicaRepertorioExtra) {
  return normalizarLinkExterno(
    musica.linkYoutube ||
    musica.youtube ||
    musica.link
  );
}

function obterDadosPlaylist(repertorio: RepertorioExtra) {
  const linkDireto = normalizarLinkExterno(
    repertorio.linkPlaylist ||
    repertorio.playlistUrl ||
    repertorio.linkDaPlaylist ||
    repertorio.linkYoutubePlaylist ||
    repertorio.playlist
  );

  const listaDireta = extrairListaYoutube(linkDireto);

  if (listaDireta && listaYoutubePodeSerCompartilhada(listaDireta)) {
    return {
      link: `https://www.youtube.com/playlist?list=${encodeURIComponent(listaDireta)}`,
      quantidade: repertorio.musicas?.length || 0,
      automatica: false,
    };
  }

  const linksMusicas = [
    ...(linkDireto ? [linkDireto] : []),
    ...(repertorio.musicas || []).map(obterLinkYoutubeMusica),
  ].filter(Boolean);

  const listaExistente = linksMusicas
    .map(extrairListaYoutube)
    .find(lista => listaYoutubePodeSerCompartilhada(lista));

  if (listaExistente) {
    return {
      link: `https://www.youtube.com/playlist?list=${encodeURIComponent(listaExistente)}`,
      quantidade: linksMusicas.length,
      automatica: false,
    };
  }

  const idsVideos = Array.from(new Set([
    ...linksMusicas.map(link => (
      extrairVideoIdYoutube(link) ||
      extrairVideoDeMixYoutube(extrairListaYoutube(link))
    )),
  ].filter(Boolean)));

  return {
    link: idsVideos.length > 1
      ? `https://www.youtube.com/watch_videos?video_ids=${idsVideos.join(',')}`
      : idsVideos.length === 1
        ? `https://www.youtube.com/watch?v=${idsVideos[0]}`
        : '',
    quantidade: idsVideos.length,
    automatica: idsVideos.length > 0,
  };
}

function CardPlaylistAnimado({
  index,
  children,
}: {
  index: number;
  children: React.ReactNode;
}) {
  const entrada = React.useRef(new Animated.Value(0)).current;

  React.useEffect(() => {
    const animacao = Animated.spring(entrada, {
      toValue: 1,
      delay: Math.min(index * 65, 520),
      friction: 8,
      tension: 68,
      useNativeDriver: true,
    });

    animacao.start();
    return () => animacao.stop();
  }, [entrada, index]);

  return (
    <Animated.View
      style={{
        opacity: entrada,
        transform: [
          {
            translateY: entrada.interpolate({
              inputRange: [0, 1],
              outputRange: [28, 0],
            }),
          },
          {
            scale: entrada.interpolate({
              inputRange: [0, 1],
              outputRange: [0.97, 1],
            }),
          },
        ],
      }}
    >
      {children}
    </Animated.View>
  );
}

function EntradaAnimada({ children }: { children: React.ReactNode }) {
  const entrada = React.useRef(new Animated.Value(0)).current;

  React.useEffect(() => {
    const animacao = Animated.parallel([
      Animated.timing(entrada, {
        toValue: 1,
        duration: 360,
        useNativeDriver: true,
      }),
    ]);

    animacao.start();
    return () => animacao.stop();
  }, [entrada]);

  return (
    <Animated.View
      style={{
        opacity: entrada,
        transform: [
          {
            translateY: entrada.interpolate({
              inputRange: [0, 1],
              outputRange: [-8, 0],
            }),
          },
          {
            scale: entrada.interpolate({
              inputRange: [0, 1],
              outputRange: [0.985, 1],
            }),
          },
        ],
      }}
    >
      {children}
    </Animated.View>
  );
}

