  async function publicarVersiculo() {
    if (!uidAtual) {
      Alert.alert('Atenção', 'Entre na sua conta para participar.');
      return;
    }

    const texto = novoVersiculo.trim();
    const referencia = novaReferencia.trim();
    if (!texto || !referencia) {
      Alert.alert('Versículo Dia', 'Preencha o versículo e a referência.');
      return;
    }

    if (publicandoVersiculo || jaPublicouVersiculoHoje) {
      if (jaPublicouVersiculoHoje) {
        Alert.alert('Versículo já publicado', 'Você já publicou seu versículo de hoje. Volte amanhã para compartilhar outro.');
      }
      return;
    }

    setPublicandoVersiculo(true);

    try {
      const diaPublicacao = obterDiaPublicacao();
      const versiculosDoUsuario = await getDocs(query(
        collection(firestore, 'interacaoVersiculos'),
        where('autorUid', '==', uidAtual)
      ));

      const publicouHoje = versiculosDoUsuario.docs.some(documento => (
        versiculoFoiPublicadoNoDia(
          { id: documento.id, ...documento.data() } as VersiculoDia,
          diaPublicacao
        )
      ));

      if (publicouHoje) {
        Alert.alert('Versículo já publicado', 'Você já publicou seu versículo de hoje. Volte amanhã para compartilhar outro.');
        return;
      }

      const versiculoRef = doc(firestore, 'interacaoVersiculos', `${uidAtual}_${diaPublicacao}`);

      await runTransaction(firestore, async transaction => {
        const versiculoExistente = await transaction.get(versiculoRef);

        if (versiculoExistente.exists()) {
          throw new Error('VERSICULO_JA_PUBLICADO_HOJE');
        }

        transaction.set(versiculoRef, {
          texto,
          referencia,
          autorUid: uidAtual,
          autorNome: nomeAtual,
          diaPublicacao,
          reacoesEmoji: {},
          criadoEm: serverTimestamp(),
        });

        transaction.set(doc(firestore, 'interacaoPontos', uidAtual), {
          nome: nomeAtual,
          pontos: increment(PONTOS_VERSICULO),
          atualizadoEm: serverTimestamp(),
        }, { merge: true });
      });

      setNovoVersiculo('');
      setNovaReferencia('');
      setFormularioVersiculoVisivel(false);
    } catch (error) {
      const jaPublicado = error instanceof Error && error.message === 'VERSICULO_JA_PUBLICADO_HOJE';

      console.log('Não foi possível publicar o versículo:', error);
      Alert.alert(
        jaPublicado ? 'Versículo já publicado' : 'Publicação não concluída',
        jaPublicado
          ? 'Você já publicou seu versículo de hoje. Volte amanhã para compartilhar outro.'
          : 'Não foi possível salvar o versículo. Verifique sua conexão e as permissões do Firestore.'
      );
    } finally {
      setPublicandoVersiculo(false);
    }
  }

  async function reagirVersiculo(versiculo: VersiculoDia, emoji: string) {
    if (!uidAtual) {
      Alert.alert('Atenção', 'Entre na sua conta para participar.');
      return;
    }

    if (reagindoVersiculoId === versiculo.id) return;

    setReagindoVersiculoId(versiculo.id);

    try {
      const primeiraReacao = await runTransaction(firestore, async transaction => {
        const versiculoRef = doc(firestore, 'interacaoVersiculos', versiculo.id);
        const versiculoSnapshot = await transaction.get(versiculoRef);

        if (!versiculoSnapshot.exists()) {
          throw new Error('Este versículo não está mais disponível.');
        }

        const reacaoAnterior = versiculoSnapshot.data().reacoesEmoji?.[uidAtual];

        if (reacaoAnterior === emoji) return false;

        transaction.update(versiculoRef, {
          [`reacoesEmoji.${uidAtual}`]: emoji,
        });

        return !reacaoAnterior;
      });

      if (primeiraReacao) {
        try {
          await adicionarPontos(uidAtual, nomeAtual, PONTOS_REACAO_VERSICULO);
        } catch (errorPontuacao) {
          console.log('Reação registrada; não foi possível atualizar a pontuação:', errorPontuacao);
        }
      }
    } catch (error) {
      console.log('Não foi possível salvar a reação do versículo:', error);
      Alert.alert(
        'Reação não salva',
        'Não foi possível registrar sua reação. Verifique as permissões do Firestore e tente novamente.'
      );
    } finally {
      setReagindoVersiculoId(null);
    }
  }

  async function enviarMensagemChat() {
    if (!uidAtual) {
      Alert.alert('Atenção', 'Entre na sua conta para participar do chat.');
      return;
    }

    const texto = novaMensagemChat.trim();
    if (!texto || enviandoMensagem) return;

    if (texto.length > 1000) {
      Alert.alert('Mensagem muito longa', 'A mensagem pode ter no máximo 1.000 caracteres.');
      return;
    }

    setEnviandoMensagem(true);

    try {
      if (editandoMensagem) {
        if (editandoMensagem.autorUid !== uidAtual) {
          throw new Error('Você pode editar somente as suas mensagens.');
        }

        await updateDoc(doc(firestore, 'interacaoMensagens', editandoMensagem.id), {
          texto,
          editada: true,
          editadoEm: serverTimestamp(),
        });
      } else {
        await addDoc(collection(firestore, 'interacaoMensagens'), {
          texto,
          autorUid: uidAtual,
          autorNome: nomeAtual,
          editada: false,
          reacoesEmoji: {},
          criadoEm: serverTimestamp(),
        });
      }

      setNovaMensagemChat('');
      setEditandoMensagem(null);
      setSeletorEmojisVisivel(false);
    } catch (error) {
      console.log('Não foi possível salvar a mensagem do chat:', error);
      Alert.alert('Mensagem não enviada', 'Verifique sua conexão e as permissões do Firestore.');
    } finally {
      setEnviandoMensagem(false);
    }
  }

  function editarMensagemChat(mensagem: MensagemChat) {
    if (mensagem.autorUid !== uidAtual) return;

    setEditandoMensagem(mensagem);
    setNovaMensagemChat(mensagem.texto);
    setSeletorEmojisVisivel(false);
  }

  function inserirEmojiNaMensagem(emoji: string) {
    setNovaMensagemChat(textoAtual => `${textoAtual}${emoji}`);
  }

  async function reagirMensagemChat(mensagem: MensagemChat, emoji: string) {
    if (!uidAtual) {
      Alert.alert('Atenção', 'Entre na sua conta para reagir às mensagens.');
      return;
    }

    if (reagindoMensagemId === mensagem.id) return;

    setReagindoMensagemId(mensagem.id);

    try {
      await runTransaction(firestore, async transaction => {
        const mensagemRef = doc(firestore, 'interacaoMensagens', mensagem.id);
        const mensagemSnapshot = await transaction.get(mensagemRef);

        if (!mensagemSnapshot.exists()) {
          throw new Error('A mensagem não existe mais.');
        }

        const reacoesAtuais = {
          ...(mensagemSnapshot.data().reacoesEmoji || {}),
        } as Record<string, string>;

        if (reacoesAtuais[uidAtual] === emoji) {
          delete reacoesAtuais[uidAtual];
        } else {
          reacoesAtuais[uidAtual] = emoji;
        }

        transaction.update(mensagemRef, {
          reacoesEmoji: reacoesAtuais,
        });
      });
    } catch (error) {
      console.log('Não foi possível salvar a reação da mensagem:', error);
      Alert.alert(
        'Reação não salva',
        'Não foi possível registrar sua reação. Verifique as permissões do Firestore e tente novamente.'
      );
    } finally {
      setReagindoMensagemId(null);
    }
  }

  async function excluirMensagemChat(mensagem: MensagemChat) {
    if (mensagem.autorUid !== uidAtual) return;

    try {
      await deleteDoc(doc(firestore, 'interacaoMensagens', mensagem.id));

      if (editandoMensagem?.id === mensagem.id) {
        setEditandoMensagem(null);
        setNovaMensagemChat('');
      }

      if (seletorReacaoMensagemId === mensagem.id) {
        setSeletorReacaoMensagemId(null);
      }
    } catch (error) {
      console.log('Não foi possível excluir a mensagem do chat:', error);
      Alert.alert('Mensagem não excluída', 'Não foi possível excluir sua mensagem. Tente novamente.');
    }
  }

  function confirmarExclusaoMensagem(mensagem: MensagemChat) {
    if (mensagem.autorUid !== uidAtual) return;

    if (Platform.OS === 'web' && typeof window !== 'undefined') {
      if (window.confirm('Deseja realmente excluir esta mensagem?')) {
        void excluirMensagemChat(mensagem);
      }
      return;
    }

    Alert.alert('Excluir mensagem', 'Deseja realmente excluir esta mensagem?', [
      { text: 'Cancelar', style: 'cancel' },
      {
        text: 'Excluir',
        style: 'destructive',
        onPress: () => { void excluirMensagemChat(mensagem); },
      },
    ]);
  }

