  async function abrirPlaylist(link: string) {
    if (!link) {
      Alert.alert(
        'Playlist indisponível',
        'Este repertório ainda não possui links do YouTube suficientes para montar a playlist.'
      );
      return;
    }

    try {
      const podeAbrir = await Linking.canOpenURL(link);
      if (!podeAbrir) throw new Error('Link não suportado');
      await Linking.openURL(link);
    } catch {
      Alert.alert('Não foi possível abrir', 'Confira os links do YouTube cadastrados neste repertório.');
    }
  }

  async function compartilharPlaylist(repertorio: RepertorioExtra, link: string) {
    if (!link) {
      Alert.alert(
        'Playlist indisponível',
        'Adicione os links do YouTube nas músicas antes de compartilhar este repertório.'
      );
      return;
    }

    const titulo = repertorio.titulo?.trim() || 'Repertório do culto';
    const data = repertorio.data?.trim();
    const quantidadeMusicas = repertorio.musicas?.length || 0;
    const mensagemSemLink = [
      '🎶 Playlist do Ministério de Louvor',
      `📋 ${titulo}`,
      data ? `📅 ${data}` : '',
      quantidadeMusicas ? `🎵 ${quantidadeMusicas} música${quantidadeMusicas === 1 ? '' : 's'}` : '',
      '',
      'Ouça o repertório que será cantado e prepare o coração para este momento de adoração:',
    ].filter(linha => linha !== '').join('\n');
    const mensagem = `${mensagemSemLink}\n${link}`;

    try {
      const navegador = (globalThis as any)?.navigator;

      if (Platform.OS === 'web' && typeof navegador?.share === 'function') {
        await navegador.share({ title: titulo, text: mensagemSemLink, url: link });
        return;
      }

      if (Platform.OS === 'web' && typeof navegador?.clipboard?.writeText === 'function') {
        await navegador.clipboard.writeText(mensagem);
        Alert.alert('Mensagem copiada', 'Agora é só colar no grupo da igreja.');
        return;
      }

      await Share.share({
        title: titulo,
        message: mensagem,
        url: link,
      });
    } catch (error: any) {
      if (error?.name === 'AbortError') return;
      Alert.alert('Não foi possível compartilhar', 'Tente novamente em alguns instantes.');
    }
  }

